// Strict Mode: Allows read, write, _exit, sigreturn only.
// Attempting other syscalls results in SIGKILL.
int enable_strict_mode(void) {
    return seccomp(SECCOMP_SET_MODE_STRICT, 0, NULL);
}

// BPF Filter Mode setup structure
struct sock_filter filter_code[] = { /* BPF Instructions here */ };

struct sock_fprog prog = {
    .len = sizeof(filter_code) / sizeof(filter_code[0]),
    .filter = filter_code,
};

// Install the custom filter (SECCOMP_SET_MODE_FILTER)
int install_bpf_filter(void) {
    // SECCOMP_FILTER_FLAG_LOG requests audit logging
    return seccomp(SECCOMP_SET_MODE_FILTER, 
                   SECCOMP_FILTER_FLAG_LOG, 
                   &prog);
}

// Ensure the mode is set before execve (SECCOMP_FILTER_FLAG_NEW_LEADER)
int install_filter_new_leader(void) {
    return seccomp(SECCOMP_SET_MODE_FILTER, 
                   SECCOMP_FILTER_FLAG_NEW_LEADER, 
                   &prog);
}
